async function cargarComentarios(){try{const r=await obtenerComentarios();mostrarComentarios(r)}catch(r){console.error("No se pudieron cargar los comentarios:",r)}}import{inicializarTema}from"./themes.min.js";import{enviarComentario,obtenerComentarios}from"./api.min.js";import{validarFormulario,mostrarEstado,mostrarComentarios}from"./ui.min.js";inicializarTema(),cargarComentarios();const formulario=document.getElementById("formulario-comentarios");formulario&&formulario.addEventListener("submit",async r=>{r.preventDefault();const o=validarFormulario(formulario);if(o.valido)try{await enviarComentario(o.datos),mostrarEstado("¡Tu comentario se guardó correctamente! 🙌","ok"),formulario.reset(),await cargarComentarios()}catch(r){console.error("Fallo la petición:",r),mostrarEstado(r.message,"error")}else mostrarEstado(o.error,"error")});